                  "text": "<strong>Hoạt động cuối tuần:</strong> Học viên tự viết câu miêu tả hoạt động giải trí hoặc sinh hoạt cùng gia đình vào cuối tuần dùng cụm at the weekend.",
                  "quote": "“At the weekend, I usually ___ with my family.”"
