                "Nhầm lẫn giữa tính từ đuôi -ed (chỉ cảm xúc người) và đuôi -ing (chỉ tính chất sự vật) (Ví dụ: I am bored vs The lesson is boring).",
                "Dùng sai giới từ theo sau tính từ: tự hào đi với of, lo lắng đi với about (Ví dụ sai: proud with, worried with → Cách đúng: proud of, worried about).",
